def flatten_integers(items):
    result = []
    def visit(values):
        for value in values:
            if isinstance(value, list):
                visit(value)
            else:
                result.append(value)
    visit(items)
    return result

coding.alternativeCode:
def flatten_integers(items):
    stack = list(reversed(items))
    result = []
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(reversed(item))
        else:
            result.append(item)
    return result

