from collections import deque

def binary_tree_depth(tree):
    if tree is None:
        return 0
    queue = deque([tree])
    depth = 0
    while queue:
        for _ in range(len(queue)):
            node = queue.popleft()
            for child in node[1:]:
                if child is not None:
                    queue.append(child)
        depth += 1
    return depth

