from collections import deque

def min_coins(coins, amount):
    if amount == 0:
        return 0
    queue = deque([(0, 0)])
    visited = {0}
    values = set(coins)
    while queue:
        total, steps = queue.popleft()
        for coin in values:
            following = total + coin
            if following == amount:
                return steps + 1
            if following < amount and following not in visited:
                visited.add(following)
                queue.append((following, steps + 1))
    return -1
